mapper.sql:
tenant_id = #{tenantId}
and deleted = 0

    and (alarm_no like concat('%', #{keyword}, '%')
    or title like concat('%', #{keyword}, '%'))


    and status = #{status}


    and alarm_level = #{alarmLevel}


    and area_id = #{areaId}


    and hazard_id = #{hazardId}


    and source_type = #{sourceType}


    and last_occurred_at >= #{occurredFrom}


    and last_occurred_at <= #{occurredTo}

mapper.select:
select * from alarm_event



order by last_occurred_at desc, id desc
limit #{offset}, #{limit}

select * from alarm_event
where tenant_id = #{tenantId}
  and dedup_key = #{dedupKey}
  and deleted = 0
  and status not in ('CLOSED', 'FALSE_CLOSED')
  and last_occurred_at >= #{windowStart}
order by last_occurred_at desc, id desc
limit 1

select * from alarm_event
where tenant_id = #{tenantId}
  and area_id = #{areaId}
  and deleted = 0
  and status not in ('CLOSED', 'FALSE_CLOSED')
order by alarm_level asc, last_occurred_at desc

select * from alarm_event
where tenant_id = #{tenantId}
  and deleted = 0
  and status = #{status}
  and alarm_level = #{alarmLevel}
  and first_occurred_at <= #{deadline}
order by first_occurred_at asc

select * from alarm_event
where tenant_id = #{tenantId}
  and deleted = 0
  and status in ('CONFIRMED', 'IN_PROGRESS')
  and alarm_level = #{alarmLevel}
  and updated_at <= #{deadline}
order by updated_at asc
